# XState Redux

Manage your Redux side effects with XState. Use 100% of XState's features.

```ts
export const counterSlice = createXStateSlice({
  // Pass in a unique, descriptive name for the slice
  name: "counter",
  // Pass in the machine
  machine: counterMachine,
  /**
   * Get the state we want to pass from the machine
   * to Redux.
   */
  getSelectedState: (state) => {
    return {
      count: state.context.count,
    };
  },
});

export const store = configureStore({
  reducer: {
    counter: counterSlice.reducer,
  },
  middleware: [createXStateMiddleware(counterSlice)],
});
```

## Getting Started

1. See [`lib/counterSlice.ts`](./lib/counterSlice.ts) to see how to create an 'XState' slice
2. See [`lib/store.ts`](./lib/store.ts) to see how to configure your Redux store to use XState.
3. Try creating your own slice! You can use any XState feature.

## Features

**Use statecharts as reducers**: Call `createMachine`, then pass it into `createXStateSlice`, and you're good to go. You can use 100% of XState's features right alongside Redux.

**Use sendParent to send events to Redux**: The Redux store is your machine's 'parent', meaning you can call `sendParent` to send actions to Redux. In future versions of XState, you'll be able to call `parent.getSnapshot()` to grab the Redux store's state.

**Colocate side effects with your Redux logic**: No more splitting out side effects from your app logic. Use `invoke`, `actions` and even spawn actors in your XState machines.

/// <reference types="next" />
/// <reference types="next/types/global" />
/// <reference types="next/image-types/global" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/basic-features/typescript for more information.

import { MiddlewareAPI, Store } from "redux";
import {
  AnyEventObject,
  EventObject,
  interpret,
  Interpreter,
  State,
  StateMachine,
} from "xstate";

/**
 * A 'slice' (to use the Redux Toolkit terminology)
 * of state which provides a reducer, and the required
 * functionality to
 */
export type XStateSlice<
  TContext = any,
  TEvent extends EventObject = AnyEventObject,
  TSelectedState = any,
> = {
  _start: (store: MiddlewareAPI) => Interpreter<TContext, any, TEvent>;
  getService: () => Interpreter<TContext, any, TEvent>;
  reducer: (
    state: TSelectedState | undefined,
    action: TEvent,
  ) => TSelectedState;
};

/**
 * Create a 'slice' which can convert an XState machine
 * into a reducer which can be used in Redux
 */
export const createXStateSlice = <
  TContext,
  TEvent extends EventObject,
  TSelectedState,
>(params: {
  name: string;
  machine: StateMachine<TContext, any, TEvent>;
  getSelectedState: (state: State<TContext, TEvent>) => TSelectedState;
}): XStateSlice<TContext, TEvent, TSelectedState> => {
  let service: Interpreter<TContext, any, TEvent> | undefined = undefined;

  const initialReduxState = params.getSelectedState(
    params.machine.initialState,
  );

  const updateEvent = (state: TSelectedState) => ({
    type: `${params.name}.xstate.update`,
    state,
  });

  /**
   * A reducer which you should pass to redux
   */
  const reducer = (
    state: TSelectedState | undefined = initialReduxState,
    event: any,
  ): TSelectedState => {
    switch (event.type) {
      case `${params.name}.xstate.update`:
        return event.state;
      default:
        return state as TSelectedState;
    }
  };

  /**
   * A function designed to be called by the middleware,
   * which starts the machine and subscribes it to the store
   *
   * There's no need to call this yourself - the middleware
   * will call it when the slice is passed in
   */
  const start = (store: MiddlewareAPI) => {
    service = interpret(params.machine, {
      parent: {
        send: (event: any) => {
          store.dispatch(event);
        },
        getSnapshot: () => {
          return store.getState();
        },
      } as any,
    }).start();

    service.subscribe((state) => {
      if (!state.changed) return;
      store.dispatch(updateEvent(params.getSelectedState(state)));
    });

    return service;
  };

  /**
   * A getter for the running XState service
   */
  const getService = () => {
    if (!service) {
      throw new Error(
        `getService was called on ${params.name} slice before slice.start() was called. slice.start() is usually called by the middleware.`,
      );
    }
    return service;
  };

  return {
    _start: start,
    reducer,
    getService,
  };
};

import type { NextPage } from "next";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "../lib/store";

const Home: NextPage = () => {
  const count = useSelector((state: RootState) => state.counter.count);
  const dispatch = useDispatch();

  return (
    <div>
      <div>
        <button
          aria-label="Increment value"
          onClick={() =>
            dispatch({
              type: "increment",
            })
          }
        >
          Increment
        </button>
        <span>{count}</span>
        <button
          aria-label="Decrement value"
          onClick={() =>
            dispatch({
              type: "decrement",
            })
          }
        >
          Decrement
        </button>
      </div>
    </div>
  );
};

export default Home;

import { Middleware } from "redux";
import { XStateSlice } from "./createXStateSlice";

/**
 * Creates a middleware which can interface between
 * XState and Redux
 */
export const createXStateMiddleware = (
  ...slices: XStateSlice[]
): Middleware => {
  return function exampleMiddleware(storeAPI) {
    const services = slices.map((slice) => slice._start(storeAPI));

    return function wrapDispatch(next) {
      return function handleAction(action) {
        const nextResult = next(action);
        services.forEach((service) => {
          service.send(action);
        });
        return nextResult;
      };
    };
  };
};

